__NUXT_JSONP__("/inclusion/columnas/urge_dignificar_el_trabajo_del_hogar_remunerado_y_el_acceso_efectivo_a_la_seguridad_social", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t){return {data:[{post:{slug:"urge_dignificar_el_trabajo_del_hogar_remunerado_y_el_acceso_efectivo_a_la_seguridad_social",title:"Urge dignificar el trabajo del hogar remunerado y el acceso efectivo a la seguridad social",date:"2025-07-14T17:05:14.425Z",img:"https:\u002F\u002Fucarecdn.com\u002F4732284d-f643-4265-b88c-8c2b13c6fd53\u002F","img-alt":"Trabajadoras del hogar",autor:"Mónica Corona y Carmen Paola Avilés",medio:p,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ftrabajo-hogar-remunerado-seguridad-social",category:g,extracto:"Es nuestra responsabilidad como sociedad asegurar que quienes sostienen el bienestar de innumerables hogares gocen de los mismos derechos y la misma dignidad que cualquier otra persona trabajadora.",toc:[],body:{type:h,children:[{type:b,tag:c,props:{},children:[{type:a,value:"El trabajo del hogar en México ha sido, históricamente, un sector paradigmático de la precariedad laboral. Nueve de cada 10 personas que lo desempeñan son mujeres, expuestas constantemente a la explotación y condiciones laborales injustas. En este contexto, las mujeres trabajadoras del hogar en México llevan años luchando por el reconocimiento pleno de sus derechos laborales y el acceso efectivo a la seguridad social, aspectos fundamentales para un trabajo digno con salarios y prestaciones justas. ¿Qué ha cambiado?"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A pesar de que en 2019 se implementaron reformas para garantizar sus derechos laborales e incorporarlas al empleo formal mediante su inscripción al Instituto Mexicano del Seguro Social (IMSS), los avances no han continuado debido a la inercia estatal y la renuencia de un número considerable de empleadores. Y es que la mera existencia de un marco legal resulta insuficiente; se necesita la participación proactiva del Estado para consolidar los esfuerzos de afiliación mediante campañas de dignificación e incentivos concretos que aseguren el acceso efectivo de estas trabajadoras a la seguridad social, garantizando así un trabajo digno y seguro."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Datos de la "},{type:b,tag:k,props:{href:"https:\u002F\u002Fwww.inegi.org.mx\u002Fcontenidos\u002Fsaladeprensa\u002Faproposito\u002F2024\u002FEAP_tdom.pdf",rel:[l,m,n],target:o},children:[{type:a,value:"Encuesta Nacional de Ocupación y Empleo (ENOE)"}]},{type:a,value:" del INEGI, publicados en 2024, nos permiten observar la gravedad del problema: 2.5 millones de personas de 15 años y más eran personas ocupadas en el trabajo doméstico remunerado en hogares en México. De estas, nueve de cada 10 eran mujeres. De ellas, el 96.3 % lo hizo en la informalidad, mientras que de los hombres, 83.4 % estuvieron en esta condición."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El trabajo del hogar (“trabajo doméstico” como también se le nombra), históricamente ha estado delegado en las mujeres debido a las concepciones, estereotipos y roles de género existentes en nuestra sociedad. Se concibe -aún tratándose de trabajadoras del hogar remuneradas, es decir, empleadas por un patrón- como un “acto de cuidado”."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Esta malinterpretación conlleva a distorsionar el tipo de relación (laboral) existente, viéndose el trabajo del hogar remunerado no como una relación laboral formal en la cual las personas trabajadoras prestan estos servicios. Esta concepción distorsionada fomenta la normalización de acuerdos verbales, bajo una supuesta “confianza” que, en la práctica, exime de cumplir con obligaciones laborales básicas. De esta forma, y aunque este trabajo es una actividad que contribuye al bienestar de millones de familias mexicanas, una amplia mayoría de mujeres trabajadoras del hogar en México lo ejercen sacrificando su propio bienestar y el de sus familias."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Pongamos un supuesto: el caso de Aurora, una trabajadora del hogar sin contrato escrito ni seguridad social, que trabaja en una casa particular bajo un acuerdo verbal. Un día, su hija de tres años enferma gravemente y el familiar que suele ayudarle a cuidarla no está disponible. Aurora pide permiso para faltar, y su empleador accede, como un “gesto de humanidad”. Sin seguridad social ni ingresos por los días no trabajados, Aurora no puede cubrir los gastos médicos ni comprar los medicamentos. Desesperada, recurre a un familiar para pedir dinero prestado y poder atender a su hija."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El caso de Aurora es la realidad de miles de mujeres en México, que están insertas en trabajos precarios y en una posición de vulnerabilidad extrema. La alarmante cifra de 96.3 % de mujeres ocupadas en este sector sin contrato escrito es un indicador contundente de la informalidad prevaleciente. De ese universo, una de cada tres mujeres trabajadoras del hogar sostiene a su familia y a las personas dependientes de ella, mientras padecen condiciones de empleo informal, mal remunerado y sin acceso a seguridad social. Esta doble carga –económica y de cuidados– se agrava por la ausencia de prestaciones que contribuyan a aliviarla, como guarderías y atención médica."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La precarización laboral en este ámbito también tiene un marcado sesgo de género. Los datos son elocuentes: las mujeres trabajadoras del hogar perciben menos salarios y gozan de menos prestaciones que sus contrapartes masculinas. Datos de la ENOE muestran que 71 % de las trabajadoras del hogar no recibió prestaciones de ningún tipo, frente al 53 % de los hombres que careció de prestaciones; el 70.4 % de las mujeres ganó hasta un salario mínimo en contraste con el 43.5 % de los hombres que ganó hasta un salario mínimo; además, casi el 23% de las mujeres obtuvo entre uno y dos salarios mínimos, frente al 37 % de los hombres. ¡Incluso dentro de un mismo sector precarizado, en donde la mayoría son mujeres, ellas siguen ganando menos! La desigualdad de género opera aún en los espacios más vulnerables del mercado laboral."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"México ha abordado esta problemática mediante la "},{type:b,tag:k,props:{href:"https:\u002F\u002Fwww.google.com\u002Furl?sa=D&q=https:\u002F\u002Fwww.ilo.org\u002Fes\u002Fresource\u002Fnews\u002Fratificacion-por-mexico-del-convenio-num-189-sobre-las-trabajadoras-y-los&ust=1752351000000000&usg=AOvVaw2d6wH3T1gLT_Tbh5y4zwYL&hl=es-419&source=gmail",rel:[l,m,n],target:o},children:[{type:a,value:"ratificación del Convenio Internacional 189 de la OIT"}]},{type:a,value:" y reformas a la Ley Federal del Trabajo (LFT) y a la Ley del Seguro Social (LSS). El programa piloto del IMSS, iniciado en 2019, fue también un paso esencial. Sin embargo, en un inicio, la Ley del Seguro Social contemplaba la afiliación de las trabajadoras del hogar remuneradas como un "},{type:b,tag:e,props:{},children:[{type:a,value:"proceso voluntario"}]},{type:a,value:", prolongando su exclusión del sistema de seguridad social. No fue sino hasta 2022 cuando se estableció como "},{type:b,tag:k,props:{href:"https:\u002F\u002Fwww.imss.gob.mx\u002Fpersonas-trabajadoras-hogar",rel:[l,m,n],target:o},children:[{type:a,value:"obligación"}]},{type:a,value:" del empleador afiliarlas. Aunque esto representó un avance significativo, a la fecha sigue siendo sólo el inicio de un proceso que exige mayor contundencia. Sigue siendo un tema pendiente atender las profundas desigualdades socioculturales y prejuicios discriminatorios que impiden la progresividad y goce de sus derechos para trabajar dignamente y libres de discriminación."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La deuda histórica y de la sociedad con las trabajadoras del hogar remuneradas es considerable. Necesitamos trascender las meras declaraciones y materializar acciones concretas. Es nuestra responsabilidad colectiva asegurar que quienes sostienen el bienestar de innumerables hogares gocen de los mismos derechos y la misma dignidad que cualquier otra persona trabajadora. Un contrato, seguridad social, y un salario justo no son concesiones o privilegios, sino derechos fundamentales que deben ser garantizados."}]}]},dir:i,path:"\u002Fcolumnas\u002Furge_dignificar_el_trabajo_del_hogar_remunerado_y_el_acceso_efectivo_a_la_seguridad_social",extension:j,createdAt:q,updatedAt:q},columnas:[{slug:"arriba_las_sirenas_negras",title:"¡Arriba las sirenas negras!",date:"2023-03-21T17:00:05.207Z",img:"https:\u002F\u002Fucarecdn.com\u002F4a69a88d-6432-46c0-9f15-96253c5a619b\u002F","img-alt":"Inclusión",autor:"Berenice Valencia",medio:p,link:"https:\u002F\u002Fwww.animalpolitico.com\u002Fanalisis\u002Finvitades\u002Farriba-las-sirenas-negras",category:g,extracto:"El racismo no se reduce a discriminación y para eliminarlo no es suficiente la representación en medios. El racismo es también la distribución desigual de recursos y poder que clasifica a las personas de acuerdo a ciertas características que se han construido socialmente como “razas”.",toc:[],body:{type:h,children:[{type:b,tag:c,props:{},children:[{type:a,value:"En septiembre del año pasado, "},{type:b,tag:e,props:{},children:[{type:a,value:"Disney"}]},{type:a,value:" estrenó el trailer de su nueva versión de "},{type:b,tag:e,props:{},children:[{type:a,value:"La Sirenita"}]},{type:a,value:", donde Halle Bailey, una actriz negra, interpreta a la sirena Ariel. Con las primeras imágenes de la "},{type:b,tag:e,props:{},children:[{type:a,value:"película"}]},{type:a,value:" llegaron críticas simplonas de adultos indignados por un "},{type:b,tag:f,props:{},children:[{type:a,value:"casting"}]},{type:a,value:" que, decían, arruinaba sus infancias, y por videos de niñas emocionadas por verse reflejadas en Ariel. También surgieron artículos explicando acertadamente por qué la indignación de esos adultos viene del racismo y por qué es importante que las infancias negras se vean representadas en la pantalla grande."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Meses antes, cuando no había trailer pero ya sabíamos que Halle Bailey sería Ariel, se volvió popular el video de una niña a quien le preguntan en la calle qué opina al respecto y ella, sin inmutarse, contesta: “no las tenemos que discriminar, arriba las "},{type:b,tag:e,props:{},children:[{type:a,value:"sirenas negras"}]},{type:a,value:"”. Me parece un gran mensaje para este "},{type:b,tag:e,props:{},children:[{type:a,value:"Día Internacional de la Eliminación de la Discriminación Racial"}]},{type:a,value:". No es suficiente con no discriminar, hay que celebrar la representación de la diversidad. Sin embargo, yo agregaría que es importante llevar nuestras conversaciones sobre racismo más allá de la discriminación y la representación."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En México, hasta hace un par de años las conversaciones sobre racismo eran prácticamente inexistentes. La idea de que México es clasista, pero no racista (como si eso fuera aceptable) no se cuestionaba. Recientemente se ha popularizado el cuestionar, al menos, la falta de representación en medios. Esto se debe, en buena medida, a "},{type:b,tag:e,props:{},children:[{type:a,value:"Poder Prieto"}]},{type:a,value:", una colectiva conformada principalmente por actrices y actores que han denunciado la discriminación racial en la industria del entretenimiento. Actores con mucha visibilidad como Tenoch Huerta y Maya Zapata han impulsado las discusiones sobre por qué en casi todos los programas de televisión, películas y comerciales mexicanos, los actores son blancos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Que los protagonistas de nuestras historias sean siempre blancos en un país como México -donde el 19 % de la población se autoidentifica como indígena, el 2 % como afrodescendiente y el 67 % autoclasifica su piel en tonos morenos- muestra una evidente discriminación racial. Discriminar significa tratar de forma diferenciada y despreciativa a una persona o grupo debido a nuestros prejuicios respecto a ese grupo. En este caso, es lo que sucede no solamente durante los "},{type:b,tag:f,props:{},children:[{type:a,value:r}]},{type:a,value:" sino en las salas donde se escriben los guiones y detrás de las cámaras de las producciones mediáticas. México y el mundo se nos presentan como si sólo existieran cierto tipo de personas, como si nuestra empatía y nuestras narrativas sólo pudieran tratarse de gente blanca. Nos presentan la blanquitud como realidad única y como aspiración."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La discriminación, por supuesto, es un problema grave. Sin embargo, el racismo no se reduce a discriminación y para eliminarlo no es suficiente la representación en medios. El racismo no sólo es que no aparezcan personas negras o de pueblos originarios en la portada de Quien. El racismo (también) es la distribución desigual de recursos y poder que clasifica a las personas de acuerdo a ciertas características que se han construido socialmente (sin fundamento biológico, por cierto) como “razas”."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Entonces, el racismo está en los "},{type:b,tag:f,props:{},children:[{type:a,value:r}]},{type:a,value:" de Televisa, sí, pero también está en el hecho de que, en México, las personas afrodescendientes tienen un mayor porcentaje de analfabetismo y menos acceso al agua entubada. Está en el sistema de salud y de justicia cuando no garantizan el acceso a sus servicios en lenguas de pueblos originarios. El racismo está en la falta de datos sobre la situación económica de la población afrodescendiente y en el despojo y contaminación de las tierras de pueblos originarios."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Existen diversos colectivos como Copera, Afrontera, Kumoontun, entre otras, que nos proporcionan claves para expandir la conversación sobre el racismo y para exigir no sólo cambios de comportamiento individual sino políticas públicas que contribuyan a eliminarlo. La discriminación racial no se terminará si no atendemos el racismo estructural. Así que, celebremos a las sirenas, superheroínas y protagonistas negras y de pueblos originarios, pero hagámoslo sabiendo que la representación no soluciona la desigualdad estructural. Debemos exigir más."}]}]},dir:i,path:"\u002Fcolumnas\u002Farriba_las_sirenas_negras",extension:j,createdAt:"2023-06-19T05:11:57.400Z",updatedAt:"2023-05-30T23:46:33.649Z"},{slug:"caravana_migrante_el_mas_reciente_reto_de_politica_exterior",title:"Caravana migrante, el más reciente reto de política exterior",date:"2019-01-21T20:32:25.569Z",img:"https:\u002F\u002Fucarecdn.com\u002Fee24c242-c206-4976-a9c9-0bec75c19113\u002F",autor:"Ana Paula Sandoval",medio:"Expansion ",link:"https:\u002F\u002Fexpansion.mx\u002Fopinion\u002F2019\u002F01\u002F21\u002Fopinion-caravana-migrante-el-mas-reciente-reto-de-politica-exterior",category:g,extracto:s,toc:[],body:{type:h,children:[{type:b,tag:c,props:{},children:[{type:b,tag:f,props:{},children:[{type:a,value:"López Obrador tiene una gran oportunidad de convertirse en un ejemplo mundial de cómo enfrentarse y resolver una problemática que ha caracterizado al siglo XXI, opina Ana Paula Sandoval."}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:s}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En esa ocasión, los migrantes centroamericanos se enfrentaron a la violencia y represión de parte de la policía mexicana que con equipos antimotines les impidió –por poco tiempo- el paso, dando lugar a una ola de violencia. Esta acción fue fuertemente criticada señalando que México accedió a hacer el “"},{type:b,tag:f,props:{},children:[{type:a,value:"trabajo sucio"}]},{type:a,value:"” a Estados Unidos, país que ha tomado una postura extremadamente crítica y restrictiva ante estos fenómenos migratorios."}]}]},dir:i,path:"\u002Fcolumnas\u002Fcaravana_migrante_el_mas_reciente_reto_de_politica_exterior",extension:j,createdAt:"2023-06-19T05:11:57.476Z",updatedAt:"2022-08-22T22:00:47.046Z"},{slug:"como_aumentar_la_productividad_en_mexico",title:"¿Cómo aumentar la productividad en México?",date:"2014-12-12T20:59:19.115Z",img:"https:\u002F\u002Fucarecdn.com\u002Fb0f9f150-1650-4570-bd56-b8aa1e6719f8\u002F",autor:"José Luis Chicoma, Eduardo Sierra",medio:" El punto sobre la i",link:"https:\u002F\u002Fmedia.wix.com\u002Fugd\u002F5a5f52_ea39ffab127545e589bd08be024e7b60.pdf",category:g,extracto:t,toc:[],body:{type:h,children:[{type:b,tag:c,props:{},children:[{type:a,value:t}]}]},dir:i,path:"\u002Fcolumnas\u002Fcomo_aumentar_la_productividad_en_mexico",extension:j,createdAt:"2023-06-19T05:11:57.536Z",updatedAt:"2022-08-22T22:00:47.047Z"}]}],fetch:{},mutations:[]}}("text","element","p","\n","strong","em","inclusion","root","\u002Fcolumnas",".md","a","nofollow","noopener","noreferrer","_blank","Animal Político","2025-11-25T01:24:03.251Z","castings","El martes pasado una nueva caravana migrante, conformada inicialmente por unas 500 personas (y que actualmente supera las 2,000), partió de Honduras con miras de llegar a Estados Unidos en busca del sueño americano. Este episodio se repite después de que una primera caravana emprendiera su camino el 13 de octubre del año pasado.","La generación de mayor conocimiento, no sólo se traduce en mejores condiciones laborales, también genera efectos positivos en la economía.")));